@pytest.mark.parametrize('frame, to_replace, value, expected', [(DataFrame({'ints': [1, 2, 3]}), 1, 0, DataFrame({'ints': [0, 2, 3]})), (DataFrame({'ints': [1, 2, 3]}, dtype=np.int32), 1, 0, DataFrame({'ints': [0, 2, 3]}, dtype=np.int32)), (DataFrame({'ints': [1, 2, 3]}, dtype=np.int16), 1, 0, DataFrame({'ints': [0, 2, 3]}, dtype=np.int16)), (DataFrame({'bools': [True, False, True]}), False, True, DataFrame({'bools': [True, True, True]})), (DataFrame({'complex': [1j, 2j, 3j]}), 1j, 0, DataFrame({'complex': [0j, 2j, 3j]})), (DataFrame({'datetime64': Index([datetime(2018, 5, 28), datetime(2018, 7, 28), datetime(2018, 5, 28)])}), datetime(2018, 5, 28), datetime(2018, 7, 28), DataFrame({'datetime64': Index([datetime(2018, 7, 28)] * 3)})), (DataFrame({'dt': [datetime(3017, 12, 20)], 'str': ['foo']}), 'foo', 'bar', DataFrame({'dt': [datetime(3017, 12, 20)], 'str': ['bar']})), (DataFrame({'A': date_range('20130101', periods=3, tz='US/Eastern'), 'B': [0, np.nan, 2]}), Timestamp('20130102', tz='US/Eastern'), Timestamp('20130104', tz='US/Eastern'), DataFrame({'A': [Timestamp('20130101', tz='US/Eastern'), Timestamp('20130104', tz='US/Eastern'), Timestamp('20130103', tz='US/Eastern')], 'B': [0, np.nan, 2]}))])
def test_replace_dtypes(self, frame, to_replace, value, expected):
    result = getattr(frame, 'replace')(to_replace, value)
    tm.assert_frame_equal(result, expected)